describe('JavaScript Alert Confirmation', () => {
  beforeEach(() => {
    cy.visit('/javascript_alerts');
  });

  it('should display confirm dialog and record user choice', () => {
    // Verify initial page state
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-messages"]').should('contain', 'Welcome to JavaScript Alerts');

    // Click the confirm button to open confirm dialog
    cy.get('[data-testid="Click for JS Confirm"]').click();

    // Verify confirm dialog appears
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Confirm Action');

    // Intercept the confirmation API call
    cy.intercept('POST', '/api/confirm-action').as('confirmAction');

    // Click the 'OK' button in the confirm dialog
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-ok"]').click();
    });

    // Verify result element shows 'You clicked: Ok'
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Ok');

    // Verify confirmation API was called
    cy.wait('@confirmAction').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should display cancel dialog and record user choice on second click', () => {
    // Verify initial page state
    cy.get('[data-testid="flash-messages"]').should('be.visible');
    cy.get('[data-testid="flash-messages"]').should('contain', 'Welcome to JavaScript Alerts');

    // Click the confirm button to open confirm dialog
    cy.get('[data-testid="Click for JS Confirm"]').click();

    // Verify confirm dialog appears
    cy.get('[data-testid="confirm-dialog"]').should('be.visible');
    cy.get('[data-testid="confirm-dialog"]').should('contain', 'Confirm Action');

    // Click the 'Cancel' button in the confirm dialog
    cy.get('[data-testid="confirm-dialog"]').within(() => {
      cy.get('[data-testid="confirm-cancel"]').click();
    });

    // Verify result element shows 'You clicked: Cancel'
    cy.get('[data-testid="result"]').should('be.visible');
    cy.get('[data-testid="result"]').should('contain', 'You clicked: Cancel');

    // Verify confirmation API was called with cancel action
    cy.wait('@confirmAction').then((interception) => {
      expect(interception.request.body.action).to.equal('cancel');
    });
  });
});
